-- PPWR Radar – Inhalte zur Verpackungs-Ebene (Migration 018), Rechtsstand 17.10.2026
-- Regeln D1–D5 (Block „verpackung“) und Entlastungs-Hinweise H01–H08.
-- Alle Datensätze: review_status entwurf, Flag „!“ bzw. „(neu 10/2026)“ → Cattwyk-Prüfung.
-- Eingespielt am 17.10.2026 über die Supabase-MCP-Schnittstelle (ein INSERT je Aufruf).

insert into rollen_regeln (regel_id, block, prioritaet, wenn_bedingung, dann_rollen, geltungsebene, fundstelle_primaer, fundstelle_sekundaer, erlaeuterung, input_variablen, flag, aktiv, review_status, rechtsstand) values
('D1','verpackung',70,
 'verpackung.art IN (transport, ecommerce, service, primaerproduktion) UND verpackung.form = formstabil UND verpackung.bezug = fertig_gekauft UND verpackung.lieferant_sitz = DE UND sitz = DE',
 'entlastung: epr_beim_lieferanten (Erzeuger und Hersteller dieser Verpackung ist der Lieferant); Nutzer: vertreiber',
 'DE',
 'Art. 3 Abs. 1 Nr. 13 und Nr. 15 lit. a VO (EU) 2025/40',
 'ZSVR: „Abgrenzung Erzeuger & Hersteller“ (formstabile Transportverpackung ist mit der Herstellung fertig; Behördeninformation); Kommissions-FAQ 2. Ed. (03.08.2026) Kap. II FAQ 5 (unverbindliche Auslegung)',
 'Fertig bezogene formstabile Transport-, Service- oder Primärproduktionsverpackung (Karton, Umschlag, Tüte) eines deutschen Lieferanten: Der Lieferant hat sie in ihre endgültige Form gebracht (Erzeuger) und erstmals in Deutschland bereitgestellt (Hersteller, lit. a). Der Nutzer ist für diese Verpackung Vertreiber mit Prüfpflicht (Registrierung des Lieferanten, vgl. B14) und braucht weder Konformitätserklärung noch Systembeteiligung dafür. Gilt nur, solange die Verpackung unverändert verwendet wird (sonst D3) und keine eigene Marke trägt (sonst A2/A5).',
 'verpackung.art, verpackung.form, verpackung.bezug, verpackung.lieferant_sitz, sitz',
 '!', true, 'entwurf', date '2026-10-17'),
('D2','verpackung',72,
 'verpackung.art IN (transport, ecommerce) UND verpackung.form = flexibel UND verpackung.bezug IN (selbst_hergestellt, selbst_zusammengefuegt) UND sitz = DE',
 'erzeuger + hersteller (für diese Verpackung)',
 'DE',
 'Art. 3 Abs. 1 Nr. 13 und Nr. 15 lit. a VO (EU) 2025/40',
 'ZSVR: „Abgrenzung Erzeuger & Hersteller“ (flexible Verpackung wie Folie oder Umreifung entsteht erst bei der Anwendung; Behördeninformation); Kommissions-FAQ 2. Ed. Kap. II FAQ 5 (unbedruckte Stretchfolie: Folienhersteller ist Erzeuger – abweichende Lesart, (!) vgl. A23, A31)',
 'Flexible Verpackung, die der Nutzer selbst anwendet (Zeitschrift einschweißen, Palette wickeln, Bündel umreifen): Nach der ZSVR-Lesart entsteht die Verpackung erst bei der Anwendung, der Anwender ist Erzeuger und Hersteller. Folge: Konformitätserklärung für die Folienverpackung, Erzeugerkennzeichnung, LUCID-Meldung der Folienmengen. (!) Die Kommission sieht bei unbedruckter Folie den Folienhersteller als Erzeuger; Cattwyk-Einordnung, welche Lesart ausgespielt wird.',
 'verpackung.art, verpackung.form, verpackung.bezug, sitz',
 '!', true, 'entwurf', date '2026-10-17'),
('D3','verpackung',74,
 'verpackung.art IN (transport, ecommerce) UND verpackung.form = formstabil UND verpackung.bezug = selbst_zusammengefuegt UND sitz = DE',
 'erzeuger + hersteller (für diese Verpackung) – mit Vorbehalt',
 'DE',
 'Art. 3 Abs. 1 Nr. 13 VO (EU) 2025/40; Art. 21 VO (EU) 2025/40',
 'ZSVR: „Versand- und Onlinehandel“, Fall B.2 (wer Materialien zur vollständigen Versandverpackung zusammenfügt, ist Erzeuger und Hersteller; Behördeninformation); Kommissions-FAQ 2. Ed. Kap. II FAQ 5 (Faltkarton ist mit Herstellung fertig – abweichend, vgl. A31)',
 'Aus Teilen zusammengefügte Versandverpackung (Faltkarton selbst aufgerichtet und verklebt, Zuschnitt, Füllmaterial): Die ZSVR ordnet den Zusammenfügenden als Erzeuger und Hersteller ein, die Kommission sieht den Kartonhersteller als Erzeuger. Bis zur Klärung wird die strengere ZSVR-Lesart mit Vorbehalt ausgespielt; der Nutzer sollte beide Wege dokumentieren (Lieferantenangaben nach Art. 16 einholen, eigene Konfektionierung festhalten).',
 'verpackung.art, verpackung.form, verpackung.bezug, sitz',
 '!', true, 'entwurf', date '2026-10-17'),
('D4','verpackung',76,
 'verpackung.art IN (transport, ecommerce, service, primaerproduktion) UND verpackung.bezug = fertig_gekauft UND verpackung.lieferant_sitz IN (EU, drittland) UND sitz = DE',
 'hersteller (erste Bereitstellung in DE); bei drittland zusätzlich importeur',
 'DE',
 'Art. 3 Abs. 1 Nr. 15 lit. a und Nr. 17 VO (EU) 2025/40; §§ 6, 7 VerpackDG (BGBl. 2026 I Nr. 207)',
 'Leitfaden C(2026) 3702 Abschn. 3 und 4 (unverbindliche Auslegung); ZSVR: „Abgrenzung Erzeuger & Hersteller“ (Inlandsvorrang)',
 'Wer leere Transportverpackung aus einem anderen Mitgliedstaat oder Drittland bezieht und erstmals in Deutschland bereitstellt, ist für diese Verpackung Hersteller (Registrierung, Systembeteiligung, Datenmeldung). Beim Bezug aus einem Drittland kommt die Importeursrolle hinzu (Prüfung, dass der Drittlandserzeuger Konformitätsbewertung und Erklärung vorgenommen hat, Art. 18). Der Erzeuger bleibt der ausländische Verpackungshersteller.',
 'verpackung.art, verpackung.bezug, verpackung.lieferant_sitz, sitz',
 '!', true, 'entwurf', date '2026-10-17'),
('D5','verpackung',78,
 'verpackung.bezug = lohnfertigung',
 'unklar (Rollen hängen vom Vertrag mit dem Dienstleister ab) – Verweis A01/A02',
 'EU/DE',
 'Art. 3 Abs. 1 Nr. 13 lit. a und Nr. 15 lit. b VO (EU) 2025/40',
 'Leitfaden C(2026) 3702 Abschn. 2 und 3 (unverbindliche Auslegung); Praxisfragen A01, A02 (Lohnabfüllung, Flag offen)',
 'Wird die Verpackung durch einen Dienstleister im Auftrag angebracht oder befüllt (Druckerei, Konfektionär, Lohnabfüller), entscheidet die Vertragsgestaltung über Erzeuger- und Herstellerrolle. Das System gibt keine Rolle vor, sondern zeigt die Fragen, die im Vertrag geklärt sein müssen, und verweist auf A01/A02. (!) Lohnfertigungs-Zuordnung ist Cattwyk-Pin (A02).',
 'verpackung.bezug',
 '!', true, 'entwurf', date '2026-10-17');

insert into entlastungs_hinweise (code, bedingung_key, titel, text, fundstellen, verweis_auslegungen, flag, review_status, rechtsstand, ausspielen) values
('H01','folie_selbst_angewendet','Umschlag oder Karton statt Folie prüfen',
 'Für Folie, die Sie selbst anwenden, tragen Sie nach der Lesart der ZSVR Erzeuger- und Herstellerpflichten: Konformitätserklärung, Erzeugerkennzeichnung, LUCID-Meldung. Bei einem fertig gekauften Umschlag oder Karton eines deutschen Lieferanten liegen beide Rollen beim Lieferanten; Sie prüfen nur dessen Registrierung. Ob ein Umschlag die Folie ersetzen kann, ist eine Frage von Produktschutz, Porto und Kosten. Das ist ein Hinweis zur Vereinfachung, keine Empfehlung für Ihren Einzelfall.',
 array['Art. 3 Abs. 1 Nr. 13 und Nr. 15 lit. a PPWR (VO (EU) 2025/40)','ZSVR: „Abgrenzung Erzeuger & Hersteller“ (Behördeninformation, keine Rechtsnorm)'], array['A31','A23'],
 '(neu 10/2026) Beruht auf der ZSVR-Lesart zu flexibler Verpackung (Regel D2); Kommissions-FAQ sieht den Folienhersteller als Erzeuger. Freigabe zusammen mit D2.', 'entwurf', date '2026-10-17', true),
('H02','lieferant_ausland_formstabil','Bezug aus Deutschland verlagert die Herstellerpflichten',
 'Kaufen Sie leere Transportverpackung im EU-Ausland oder in einem Drittland, sind Sie der erste Bereitsteller in Deutschland und damit Hersteller: Registrierung, Systembeteiligung, Datenmeldung für diese Verpackung. Beziehen Sie dieselbe Verpackung von einem in Deutschland ansässigen Lieferanten, übernimmt dieser die Herstellerrolle, und Sie prüfen nur seine Registrierung. Beim Drittlandbezug kommt die Importeurspflicht hinzu. Ob der Wechsel wirtschaftlich sinnvoll ist, entscheiden Sie.',
 array['Art. 3 Abs. 1 Nr. 15 lit. a und Nr. 17 PPWR (VO (EU) 2025/40)','Art. 18 PPWR','§§ 6, 7 VerpackDG (BGBl. 2026 I Nr. 207)'], array['A19','B14'],
 '(neu 10/2026) Regel D4; Fundstellen am Volltext pinnen (lit. a vs. lit. b bei verpackter Ware).', 'entwurf', date '2026-10-17', true),
('H03','selbst_zusammengefuegt','Fertig konfektionierte Verpackung kaufen',
 'Wer Kartons selbst aufrichtet und verklebt oder Zuschnitte selbst konfektioniert, wird nach der Lesart der ZSVR Erzeuger und Hersteller der Versandverpackung. Bei fertig bezogener, unverändert verwendeter Verpackung eines deutschen Lieferanten liegen diese Rollen beim Lieferanten. Die Kommission sieht das weniger streng, die Frage ist offen. Wer die Unsicherheit vermeiden will, kauft fertig konfektioniert und lässt sich die Angaben nach Art. 16 PPWR vom Lieferanten geben.',
 array['Art. 3 Abs. 1 Nr. 13 PPWR (VO (EU) 2025/40)','Art. 16 Abs. 1 PPWR','ZSVR: „Versand- und Onlinehandel“, Fall B.2 (Behördeninformation)','Kommissions-FAQ 2. Ed. Kap. II FAQ 5 (unverbindliche Auslegung)'], array['A31','A30'],
 '(neu 10/2026) Regel D3; Divergenz Kommission/ZSVR offen.', 'entwurf', date '2026-10-17', true),
('H04','kleinst_lieferant_eu','Als Kleinstunternehmen: Lieferant im selben Mitgliedstaat',
 'Lassen Sie als Kleinstunternehmen Verpackung unter eigener Marke herstellen, geht die Erzeugerrolle auf den Lieferanten über, wenn dieser im selben Mitgliedstaat sitzt (Art. 3 Abs. 1 Nr. 13 lit. b PPWR). Sitzt Ihr Lieferant im Ausland, bleiben Sie Erzeuger mit Konformitätsbewertung, Dokumentation und Erklärung. Ein Lieferant in Deutschland entlastet Sie von diesen Pflichten; die Kleinstunternehmens-Schwelle (unter 10 Beschäftigte, Umsatz oder Bilanzsumme bis 2 Mio. Euro) müssen Sie dafür einhalten.',
 array['Art. 3 Abs. 1 Nr. 13 lit. b PPWR (VO (EU) 2025/40)','Empfehlung 2003/361/EG'], array['A04','A05','A06'],
 '(neu 10/2026) Regel A3 (Flag offen: Verbund-/Franchise-Berechnung U8).', 'entwurf', date '2026-10-17', true),
('H05','transport_leerraum','Kartongrößen jetzt schon auf die Leerraumquote ausrichten',
 'Ab dem 01.01.2030 darf der Leerraum in Um-, Transport- und E-Commerce-Verpackungen 50 Prozent nicht überschreiten. Wer Verpackungsgrößen oder Füllmaterial jetzt neu festlegt, spart sich eine zweite Umstellung. Für Versandkartons heißt das: wenige passende Größen statt eines Universalkartons.',
 array['Art. 24 Abs. 1 PPWR (VO (EU) 2025/40)'], array[]::text[],
 '(neu 10/2026) Rechtsakt zur Berechnungsmethode steht aus (Anforderung #18).', 'entwurf', date '2026-10-17', true),
('H06','vertreiber_lieferant_pruefen','Registrierungsnummer des Lieferanten einholen',
 'Für Verpackung, bei der Ihr Lieferant Hersteller ist, müssen Sie als Vertreiber prüfen, dass er im Verpackungsregister LUCID registriert ist, bevor Sie die Verpackung weitergeben. Lassen Sie sich die LUCID-Registrierungsnummer schriftlich bestätigen und legen Sie sie zur Verpackung ab. Das ersetzt für diese Verpackung Ihre eigene Lizenzierung nicht automatisch, belegt aber, dass die Pflicht beim Lieferanten liegt.',
 array['Art. 19 PPWR (VO (EU) 2025/40)','Art. 44 PPWR','§ 13 Abs. 3 VerpackDG (BGBl. 2026 I Nr. 207)','§ 6 Abs. 4 VerpackDG'], array['B14'],
 '(neu 10/2026) Fundstellen aus B14 übernommen, am Volltext pinnen.', 'entwurf', date '2026-10-17', true),
('H07','erzeuger_mehrere_bestandteile','Eine Konformitätserklärung je Verpackungseinheit',
 'Besteht Ihre Verpackung aus mehreren Bestandteilen (Karton, Einlage, Folie), die zusammen in Verkehr gebracht werden, kann eine Konformitätsbewertung und eine Erklärung die gesamte Einheit abdecken. Sie brauchen also nicht je Bestandteil ein Dokument, wohl aber je Bestandteil die Nachweise des Lieferanten. Legen Sie Verpackungen, die immer zusammen versendet werden, als eine Einheit an.',
 array['Art. 38 und 39 PPWR (VO (EU) 2025/40)','Kommissions-FAQ 2. Ed. Kap. XV FAQ 5 (unverbindliche Auslegung)'], array['C16','C03'],
 '(neu 10/2026) Begriff „Verpackungseinheit“ nicht normiert; vgl. C16.', 'entwurf', date '2026-10-17', true),
('H08','erzeuger_lagerware','Lagerbestände nicht umetikettieren',
 'Für Verpackung, die vor dem 12.08.2026 produziert, aber noch nicht in Verkehr gebracht wurde, erwartet die Kommission keine Umetikettierung: Die Erzeugerangaben nach Art. 15 Abs. 5 und 6 dürfen über Begleitdokumente mitgegeben werden, eine Chargennummer genügt. Dokumentieren Sie je Charge Name, Marke, Anschrift und Kontaktweg in den Lieferpapieren, statt Bestände neu zu bedrucken.',
 array['Art. 15 Abs. 5 und 6 PPWR (VO (EU) 2025/40)','Kommissions-FAQ 2. Ed. Kap. X FAQ 5 (unverbindliche Auslegung)'], array['C15','C01'],
 '(neu 10/2026) Spannung zu #10/C01 (kein Abverkaufsprivileg für stoffliche Anforderungen); vgl. C15.', 'entwurf', date '2026-10-17', true);
